// Observe actual Unity serialization before/after force importing source assets.
// No SetValue, SerializedProperty write, SaveAssets, prefab save or game patch.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;using UnityEditor;
public static class GodsPVZSerializedReferenceProbeR27 {
 const BindingFlags Fields=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
 [Serializable] public class AudioItem {public int index;public bool @null;public string name;}
 [Serializable] public class AudioPlan {public int count;public AudioItem[] items;}
 [Serializable] public class SourceOwner {public string source_path;}
 [Serializable] public class ZombieSourcePlan {public SourceOwner[] plans;}
 [Serializable] public class MethodBodyRow {public string type,method,assembly,location,assembly_sha256,metadata_token,il_hex,error;}
 [Serializable] public class FieldRow {public string field,type,attributes,value,serialized_type,serialized_value;public bool unity_object_assignable,property_found;public int serialized_array_size=-1;}
 [Serializable] public class ObjectRow {public string phase,route,path,type,identity,mono_script_class,editor_json;public List<FieldRow> fields=new List<FieldRow>();public List<string> property_paths=new List<string>(),children=new List<string>();}
 [Serializable] public class Change {public string file,before,after;}
 [Serializable] public class Report {public string scope="ACTUAL_UNITY_SERIALIZATION_AND_FORCE_IMPORT_OBSERVATION_NO_SOURCE_OR_GAME_PATCH",candidate_sha256;public bool collection_complete,source_bytes_unchanged,game_dll_unchanged,source_references_rewritten=false,game_fields_assigned=false,device_execution=false;public int import_count;public List<string> imports=new List<string>(),assemblies=new List<string>(),exceptions=new List<string>();public List<ObjectRow> objects=new List<ObjectRow>();public List<Change> source_changes=new List<Change>();public List<MethodBodyRow> runtime_support_methods=new List<MethodBodyRow>();}
 static Type Named(string n){return AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType(n,false)).FirstOrDefault(t=>t!=null);}
 static string Hash(string path){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
 static string Folder{get{var s=Environment.GetEnvironmentVariable("GODSPVZ_STARTUP_EVIDENCE");if(String.IsNullOrEmpty(s))throw new InvalidOperationException("Evidence folder required");return s;}}
 public static AudioPlan ExpectedAudio(){var path=Environment.GetEnvironmentVariable("GODSPVZ_ORIGINAL_AUDIO_PLAN");if(String.IsNullOrEmpty(path))throw new InvalidOperationException("Original audio plan required");var p=JsonUtility.FromJson<AudioPlan>(File.ReadAllText(path));if(p.count!=76||p.items==null||p.items.Length!=76||p.items.Where((x,i)=>x.index!=i).Any())throw new InvalidOperationException("Wrong original audio input");return p;}
 public static bool AudioMatches(object value,out string detail){var list=value as IList;var expected=ExpectedAudio();if(list==null||list.Count!=76){detail="count="+(list==null?-1:list.Count);return false;}for(int i=0;i<76;i++){var actual=list[i] as UnityEngine.Object;var row=expected.items[i];if(row.@null?actual!=null:actual==null||actual.name!=row.name){detail="index="+i+" actual="+(actual==null?"null":actual.name)+" expected="+(row.@null?"null":row.name);return false;}}detail="76 ordered slots, 63 named AudioClips and 13 original nulls";return true;}
 static string Describe(object x){if(x==null)return "null";var u=x as UnityEngine.Object;if(x is UnityEngine.Object){if(u==null)return "destroyed Unity object";string guid;long id;bool has=AssetDatabase.TryGetGUIDAndLocalFileIdentifier(u,out guid,out id);return u.GetType().AssemblyQualifiedName+" name="+u.name+" instance="+u.GetInstanceID()+" asset="+AssetDatabase.GetAssetPath(u)+" guid="+(has?guid:"")+" localID="+(has?id.ToString(System.Globalization.CultureInfo.InvariantCulture):"unavailable");}var list=x as IList;if(list!=null)return "count="+list.Count+" ["+String.Join(",",list.Cast<object>().Take(80).Select(v=>v is UnityEngine.Object?((UnityEngine.Object)v==null?"null":((UnityEngine.Object)v).name):v==null?"null":Convert.ToString(v,System.Globalization.CultureInfo.InvariantCulture)).ToArray())+"]";return Convert.ToString(x,System.Globalization.CultureInfo.InvariantCulture);}
 static void Observe(Report report,string phase,string route,string path,string ownerName,string[] names){
  GameObject prefab=route=="AssetDatabase"?AssetDatabase.LoadAssetAtPath<GameObject>(path):Resources.Load<GameObject>(path.Substring("Assets/Resources/".Length,path.Length-"Assets/Resources/".Length-".prefab".Length));
  var row=new ObjectRow{phase=phase,route=route,path=path,type=ownerName,identity=Describe(prefab)};report.objects.Add(row);if(prefab==null)return;
  var owner=prefab.GetComponents<MonoBehaviour>().SingleOrDefault(c=>c!=null&&c.GetType().FullName==ownerName);if(owner==null){row.identity+="; owner missing";return;}row.identity=Describe(owner);var script=MonoScript.FromMonoBehaviour(owner);row.mono_script_class=Describe(script)+" class="+(script==null||script.GetClass()==null?"null":script.GetClass().AssemblyQualifiedName);row.editor_json=EditorJsonUtility.ToJson(owner);
  var serialized=new SerializedObject(owner);serialized.Update();var iterator=serialized.GetIterator();for(bool enter=true;iterator.Next(enter);enter=true){row.property_paths.Add(iterator.propertyPath+":"+iterator.propertyType+":"+iterator.type);if(row.property_paths.Count>=180)break;}
  foreach(string name in names){var f=owner.GetType().GetField(name,Fields);var p=serialized.FindProperty(name);var fr=new FieldRow{field=name,type=f==null?"MISSING_FIELD":f.FieldType.AssemblyQualifiedName,attributes=f==null?"":f.Attributes+" ["+String.Join(",",CustomAttributeData.GetCustomAttributes(f).Select(a=>a.AttributeType.AssemblyQualifiedName).ToArray())+"]",unity_object_assignable=f!=null&&typeof(UnityEngine.Object).IsAssignableFrom(f.FieldType),value=f==null?"MISSING_FIELD":Describe(f.GetValue(owner)),property_found=p!=null};if(p!=null){fr.serialized_type=p.propertyType+":"+p.type;if(p.isArray)fr.serialized_array_size=p.arraySize;if(p.propertyType==SerializedPropertyType.ObjectReference)fr.serialized_value=Describe(p.objectReferenceValue)+" referenceInstance="+p.objectReferenceInstanceIDValue;}row.fields.Add(fr);}
  foreach(var t in prefab.GetComponentsInChildren<Transform>(true)){var relative=t.name;for(var p=t.parent;p!=null&&p!=prefab.transform;p=p.parent)relative=p.name+"/"+relative;row.children.Add(relative+" "+Describe(t.gameObject));foreach(var c in t.GetComponents<MonoBehaviour>())if(c!=null)row.children.Add(relative+" "+Describe(c));}
 }
 static void Snapshot(Report r,string phase){foreach(var route in new[]{"AssetDatabase","Resources"}){Observe(r,phase,route,"Assets/Resources/prefabs/ui/smallobjects/ZombieWindow.prefab","Almanac_ZombieWindow",new[]{"zombiePortrait","questionMark","checkMark","eliteMark","bossMark","button"});Observe(r,phase,route,"Assets/Resources/prefabs/managers/ZombieManager.prefab","ZombieManager",new[]{"audioClip_zombie","zombiePrefabList","zombieList"});foreach(string name in new[]{"CherryBlaster","ChomperViking","NutKnight","Peasniper","PotatoMortar","Repearbalester","SnowpeaWitch","StarfruitSwordImmortal","Sunflower"}){var files=Directory.GetFiles(Path.Combine(Application.dataPath,"Resources"),"*.prefab",SearchOption.AllDirectories).Where(p=>String.Equals(Path.GetFileNameWithoutExtension(p),name,StringComparison.OrdinalIgnoreCase)).ToArray();if(files.Length!=1)throw new InvalidOperationException("Unique original Plant prefab required: "+name);string path="Assets"+files[0].Substring(Application.dataPath.Length).Replace('\\','/');Observe(r,phase,route,path,"Plant",Named("Plant").GetFields(Fields).Select(f=>f.Name).ToArray());}
   string planFile=Environment.GetEnvironmentVariable("GODSPVZ_ORIGINAL_ZOMBIE_PLAN");if(!String.IsNullOrEmpty(planFile)){var plan=JsonUtility.FromJson<ZombieSourcePlan>(File.ReadAllText(planFile));if(plan.plans==null||plan.plans.Length!=26)throw new InvalidOperationException("Exactly 26 original Zombie resources required");var assetPaths=AssetDatabase.GetAllAssetPaths();foreach(var owner in plan.plans){var matches=assetPaths.Where(p=>String.Equals(p,owner.source_path,StringComparison.OrdinalIgnoreCase)).ToArray();if(matches.Length!=1)throw new InvalidOperationException("Unique original Zombie path required: "+owner.source_path);Observe(r,phase,route,matches[0],"Zombie",Named("Zombie").GetFields(Fields).Select(f=>f.Name).ToArray());}}
  }}
 static Dictionary<string,string> Inventory(){return Directory.GetFiles(Application.dataPath,"*",SearchOption.AllDirectories).ToDictionary(p=>p,p=>Hash(p),StringComparer.Ordinal);}
 static void Save(Report r){Directory.CreateDirectory(Folder);File.WriteAllText(Path.Combine(Folder,"r27-serialization-reimport-probe.json"),JsonUtility.ToJson(r,true));}
 static void ObserveSupportCode(Report r,string stage="serialization-probe"){
  var type=Named("Unity.VisualScripting.ComponentHolderProtocol");if(type==null){r.runtime_support_methods.Add(new MethodBodyRow{type="Unity.VisualScripting.ComponentHolderProtocol",error="TYPE_NOT_LOADED_NO_CLAIM_ABOUT_ITS_IMPLEMENTATION"});return;}string location=type.Assembly.Location;string hash=File.Exists(location)?Hash(location):"unavailable";string output=Environment.GetEnvironmentVariable("GODSPVZ_RUNTIME_SUPPORT_OUTPUT");if(!String.IsNullOrEmpty(output)&&File.Exists(location)){output=Path.Combine(output,stage);Directory.CreateDirectory(output);string path=Path.Combine(output,Path.GetFileName(location));if(File.Exists(path))throw new InvalidOperationException("Never overwrite runtime support observation");File.Copy(location,path);if(Hash(path)!=hash)throw new InvalidOperationException("Runtime support copy mismatch");}
  foreach(var method in type.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Where(m=>m.Name=="AddComponent"||m.Name=="GameObject")){var row=new MethodBodyRow{type=type.FullName,method=method.ToString(),assembly=type.Assembly.FullName,location=location,assembly_sha256=hash,metadata_token="0x"+method.MetadataToken.ToString("X8")};try{var body=method.GetMethodBody();row.il_hex=body==null?"NO_MANAGED_BODY":BitConverter.ToString(body.GetILAsByteArray()).Replace("-","").ToLowerInvariant();}catch(Exception e){row.error=e.GetType().FullName+": "+e.Message;}r.runtime_support_methods.Add(row);}
 }
 public static void CaptureLoadedSupportAfterUI(){var r=new Report{candidate_sha256=Hash(Path.Combine(Application.dataPath,"Plugins/GodsPVZRuntime1.dll"))};if(r.candidate_sha256!="eef6c35a2dceb0c38d1032837204abaff56f3a4c4d029ca47d76ff496fd69293")throw new InvalidOperationException("Wrong actual UI support candidate");ObserveSupportCode(r,"after-real-ui");File.WriteAllText(Path.Combine(Folder,"r27-actual-ui-runtime-support.json"),JsonUtility.ToJson(r,true));}
 public static void Run(){
  var r=new Report();string plugin=Path.Combine(Application.dataPath,"Plugins/GodsPVZRuntime1.dll");r.candidate_sha256=Hash(plugin);if(r.candidate_sha256!="eef6c35a2dceb0c38d1032837204abaff56f3a4c4d029ca47d76ff496fd69293")throw new InvalidOperationException("Wrong probe candidate");var before=Inventory();Save(r);
  try{
   foreach(var a in AppDomain.CurrentDomain.GetAssemblies().Where(a=>a.GetName().Name.Contains("UnityEngine")||a.GetName().Name.Contains("GodsPVZ"))){string location;try{location=a.Location;}catch{location="unavailable";}r.assemblies.Add(a.FullName+" "+location);}
   ObserveSupportCode(r);Snapshot(r,"before-force-import");Save(r);var paths=AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith("Assets/",StringComparison.Ordinal)&&(p.EndsWith(".prefab",StringComparison.Ordinal)||p.EndsWith(".unity",StringComparison.Ordinal))).OrderBy(p=>p,StringComparer.Ordinal).ToArray();if(paths.Length<100)throw new InvalidOperationException("Missing original source asset inventory");
   foreach(var path in paths){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);r.imports.Add(path);r.import_count++;if(r.import_count%20==0)Save(r);}
   EditorUtility.UnloadUnusedAssetsImmediate();Snapshot(r,"after-force-import");r.collection_complete=true;
  }catch(Exception e){r.exceptions.Add(e.ToString());}
  finally{var after=Inventory();foreach(var p in before.Keys.Union(after.Keys)){string a,b;before.TryGetValue(p,out a);after.TryGetValue(p,out b);if(a!=b)r.source_changes.Add(new Change{file=p.Substring(Application.dataPath.Length+1),before=a,after=b});}r.source_bytes_unchanged=r.source_changes.Count==0;r.game_dll_unchanged=Hash(plugin)==r.candidate_sha256;Save(r);}
  if(!r.collection_complete||!r.source_bytes_unchanged||!r.game_dll_unchanged)throw new InvalidOperationException("Serialization probe incomplete or source bytes changed; inspect preserved evidence");
 }
}
